package cn.bidcheck.verification.engine;

import cn.bidcheck.domain.Domain.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class PricingInputValidatorTest {
    static String roster="有效投标人价格名单（不含税）\n甲公司：投标报价100万元\n乙公司：投标报价1200000元";
    static Document document(String text){return new Document("prices","p","BID","价格资料",1,"hash","",cn.bidcheck.compat.Java8Api.listOf(new Page(7,text,"PARAGRAPH","DOCX","")),cn.bidcheck.compat.Java8Api.listOf());}
    static Map<String,Object> source(String quote){return cn.bidcheck.compat.Java8Api.mapOf("documentId", "prices", "page", 7, "quote", quote);}
    static Map<String,Object> entry(String bidder,String value,String unit,String quote){return new LinkedHashMap<>(cn.bidcheck.compat.Java8Api.mapOf("bidder", bidder, "price", value, "unit", unit, "source", source(quote)));}
    static Map<String,Object> input(){return new LinkedHashMap<>(cn.bidcheck.compat.Java8Api.mapOf("confirmed", true, "rosterComplete", true, "arithmeticCorrectionsConfirmed", true, "taxBasis", "EXCLUDING_TAX", "targetBidder", "甲公司", "rosterSource", source(roster), "entries", cn.bidcheck.compat.Java8Api.listOf(entry("甲公司","100","万元","甲公司：投标报价100万元"), entry("乙公司","1200000","元","乙公司：投标报价1200000元"))));}
    @Test void normalizesYuanAndKeepsWordLocationAndNonOfficialProvenance(){Map<String,Object> result=PricingInputValidator.validate(input(),cn.bidcheck.compat.Java8Api.listOf(document(roster)));List<Map<String,Object>> entries=(List<Map<String,Object>>)result.get("entries");assertEquals("1000000",entries.get(0).get("price"));assertEquals("PARAGRAPH",((Evidence)entries.get(0).get("evidence")).locationType());assertEquals("USER_CONFIRMED_DATA_SNAPSHOT",result.get("provenanceStatus"));}
    @Test void emptyPricingIsOptional(){assertEquals(cn.bidcheck.compat.Java8Api.mapOf(),PricingInputValidator.validate(null,cn.bidcheck.compat.Java8Api.listOf()));assertEquals(cn.bidcheck.compat.Java8Api.mapOf(),PricingInputValidator.validate(cn.bidcheck.compat.Java8Api.mapOf(),cn.bidcheck.compat.Java8Api.listOf()));}
    @Test void invalidRosterCannotBeRelabeledEffective(){String text=roster.replace("有效投标人","无效投标人");Map<String,Object> in=input();in.put("rosterSource",source(text));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(text))));}
    @Test void allThreeConfirmationsAreRequired(){Map<String,Object> in=input();in.put("arithmeticCorrectionsConfirmed",false);assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(roster))));}
    @Test void rosterMustExplicitlyExcludeTax(){String text=roster.replace("不含税","含税");Map<String,Object> in=input();in.put("rosterSource",source(text));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(text))));}
    @Test void duplicateBidderAndMissingTargetRejected(){Map<String,Object> in=input();in.put("entries",cn.bidcheck.compat.Java8Api.listOf(entry("甲公司","100","万元","甲公司：投标报价100万元"), entry("甲公司","100","万元","甲公司：投标报价100万元")));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(roster))));in.put("entries",cn.bidcheck.compat.Java8Api.listOf(entry("乙公司","1200000","元","乙公司：投标报价1200000元")));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(roster))));}
    @Test void cannotUseNeighborBidderOrDecimalPrefix(){Map<String,Object> in=input();in.put("entries",cn.bidcheck.compat.Java8Api.listOf(entry("甲公司","1200000","元","甲公司：投标报价100万元\n乙公司：投标报价1200000元")));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(roster))));in.put("entries",cn.bidcheck.compat.Java8Api.listOf(entry("甲公司","10","万元","甲公司：投标报价100万元")));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(roster))));}
    @Test void contractPriceCannotSubstituteBidPrice(){String line="甲公司合同报价100万元",text=roster+"\n"+line;Map<String,Object> in=input();in.put("entries",cn.bidcheck.compat.Java8Api.listOf(entry("甲公司","100","万元",line)));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(text))));}
    @Test void otherAmountUnitCannotBeBorrowed(){String line="甲公司投标报价100元，注册资本100万元",text=roster+"\n"+line;Map<String,Object> in=input();in.put("entries",cn.bidcheck.compat.Java8Api.listOf(entry("甲公司","100","万元",line)));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(text))));}
    @Test void sourceMustBeExactSelectedDocumentPosition(){Map<String,Object> in=input();in.put("rosterSource",cn.bidcheck.compat.Java8Api.mapOf("documentId", "outside", "page", 7, "quote", roster));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(roster))));in.put("rosterSource",cn.bidcheck.compat.Java8Api.mapOf("documentId", "prices", "page", 1, "quote", roster));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(roster))));}
    @Test void zeroAndNegativeOrExponentPricesRejected(){for(String number:cn.bidcheck.compat.Java8Api.listOf("0", "-1", "1E2")){Map<String,Object> in=input();in.put("entries",cn.bidcheck.compat.Java8Api.listOf(entry("甲公司",number,"万元","甲公司：投标报价100万元")));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(roster))));}}
    @Test void explicitlyIncludedTaxEntryRejected(){String line="甲公司含税投标报价100万元",text=roster+"\n"+line;Map<String,Object> in=input();in.put("entries",cn.bidcheck.compat.Java8Api.listOf(entry("甲公司","100","万元",line)));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(text))));}
    @Test void equivalentInputUnitsAreConvertedAgainstOriginalPriceToken(){String list="本项目全部有效投标人不含税评标价名单：甲公司、乙公司。已完成算术修正。",a="甲公司 不含税评标价：1000000元",b="乙公司 不含税评标价：100万元";Map<String,Object> in=input();in.put("rosterSource",source(list));in.put("entries",cn.bidcheck.compat.Java8Api.listOf(entry("甲公司","100","万元",a), entry("乙公司","1000000","元",b)));Map<String,Object> result=PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(list+"\n"+a+"\n"+b)));List<Map<String,Object>> rows=(List<Map<String,Object>>)result.get("entries");assertEquals("1000000",rows.get(0).get("price"));assertEquals("元",rows.get(0).get("sourceUnit"));assertEquals("1000000",rows.get(1).get("price"));}
    @Test void sameLineOtherBidderPriceCannotBeBorrowed(){for(String separator:cn.bidcheck.compat.Java8Api.listOf("；", "，")){String row="甲公司 不含税评标价100元"+separator+"乙公司 不含税评标价200元";Map<String,Object> in=input();in.put("entries",cn.bidcheck.compat.Java8Api.listOf(entry("甲公司","200","元",row)));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(roster+"\n"+row))));}}
    @Test void canonicalYuanBoundsMatchPricingEngine(){for(String amount:cn.bidcheck.compat.Java8Api.listOf("1000000000000000000", "0.0000001")){String row="甲公司不含税评标价"+amount+"元";Map<String,Object> in=input();in.put("entries",cn.bidcheck.compat.Java8Api.listOf(entry("甲公司",amount,"元",row)));assertThrows(IllegalArgumentException.class,()->PricingInputValidator.validate(in,cn.bidcheck.compat.Java8Api.listOf(document(roster+"\n"+row))));}}
}
